// [frase, verbo entre paréntesis, [respuestas válidas], explicación]
export const TN = [
 ["I ___ in Madrid since 2019.","live",["have lived","have been living"],"<b>Present perfect</b>: empezó en el pasado y sigue ahora. <mark>since</mark> + momento concreto."],
 ["Yesterday we ___ to the beach.","go",["went"],"<b>Past simple</b>: acción terminada con momento concreto (<mark>yesterday</mark>). Go es irregular: go, went, gone."],
 ["Look! It ___.","rain",["is raining"],"<b>Present continuous</b>: está pasando ahora mismo (<mark>Look!</mark>)."],
 ["She usually ___ to school.","walk",["walks"],"<b>Present simple</b>: hábito (<mark>usually</mark>). No olvides la <b>-s</b> con he/she/it."],
 ["While I ___, the phone rang.","cook",["was cooking"],"<b>Past continuous</b>: acción en progreso interrumpida por otra (<mark>while</mark>)."],
 ["I ___ to London.","never / be",["have never been"],"<b>Present perfect</b> para experiencias: <mark>never</mark> va entre have y el participio."],
 ["When we arrived, the film ___.","already / start",["had already started"],"<b>Past perfect</b>: pasó antes de otra acción pasada (llegamos)."],
 ["I think it ___ sunny tomorrow.","be",["will be"],"<b>Will</b> para predicciones y opiniones (<mark>I think</mark>)."],
 ["We ___ my grandma next weekend. We've already bought the tickets.","visit",["are going to visit","are visiting"],"Plan decidido: <b>going to</b> o <b>present continuous</b>."],
 ["Have you ever ___ sushi?","eat",["eaten"],"<b>Present perfect</b> (<mark>ever</mark>) usa el participio: eat, ate, <b>eaten</b>."],
 ["I ___ Tom last week.","not / see",["did not see"],"<b>Past simple</b> negativo: didn't + infinitivo (no «didn't saw»)."],
 ["She ___ her homework, so she can go out now.","just / finish",["has just finished"],"<b>Present perfect</b> con <mark>just</mark>: acaba de pasar."],
 ["At 8 pm last night I ___ TV.","watch",["was watching"],"<b>Past continuous</b>: en progreso a una hora concreta del pasado."],
 ["Water ___ at 100 degrees.","boil",["boils"],"<b>Present simple</b>: verdades generales."],
 ["I ___ him for ten years.","know",["have known"],"Know no va en continuo. <b>Present perfect</b> + <mark>for</mark> + duración."],
 ["Don't worry, I ___ you with the bags.","help",["will help"],"<b>Will</b> para decisiones y ofrecimientos en el momento."],
 ["My train ___ at 7:15 tomorrow morning.","leave",["leaves"],"<b>Present simple</b> para horarios fijos, aunque sea futuro."],
 ["By the time I got to the station, the train ___.","leave",["had left"],"<b>Past perfect</b> con <mark>by the time</mark>: ya había pasado."],
 ["I'm tired because I ___ all day.","work",["have been working","have worked"],"<b>Present perfect continuous</b>: actividad larga con resultado ahora (estoy cansado)."],
 ["He ___ coffee.","not / like",["does not like"],"<b>Present simple</b> negativo con he: doesn't + infinitivo (sin -s)."],
 ["Three years ago I ___ learning English.","start",["started"],"<b>Past simple</b>: <mark>ago</mark> siempre va con pasado simple y detrás de la cantidad de tiempo."],
 ["If it rains tomorrow, we ___ at home.","stay",["will stay"],"<b>Primer condicional</b>: if + presente, will + infinitivo."],
 ["If I ___ more money, I would travel more.","have",["had"],"<b>Segundo condicional</b>: if + pasado, would + infinitivo."],
 ["This letter ___ by my grandfather in 1950.","write",["was written"],"<b>Pasiva en pasado</b>: was/were + participio."],
 ["English ___ in many countries.","speak",["is spoken"],"<b>Pasiva en presente</b>: is/are + participio."],
 ["I ___ this film last month and I loved it.","see",["saw"],"<b>Past simple</b> con <mark>last month</mark>. Nunca «have seen» con last/yesterday/ago."],
 ["Right now they ___ lunch.","have",["are having"],"<b>Present continuous</b>: <mark>right now</mark>."],
 ["When I was a child, I ___ football every day.","play",["used to play","played"],"<b>Used to</b> para hábitos pasados que ya no haces (también vale past simple)."],
 ["Have you ___ your homework yet?","finish",["finished"],"<b>Present perfect</b> en pregunta con <mark>yet</mark>: Have you finished...?"],
 ["How long ___ English?","you / study",["have you been studying","have you studied"],"<b>How long</b> + present perfect (continuous) para duración hasta ahora."]
];

